'use strict';
const $=id=>document.getElementById(id);
let selected='Operations', account=null, provider=null, connecting=false;
const providers=[];
window.addEventListener('eip6963:announceProvider',event=>{const p=event.detail?.provider;if(p&&!providers.includes(p))providers.push(p)});
window.dispatchEvent(new Event('eip6963:requestProvider'));
function renderWallet(){ $('wallet-label').textContent=account?`${account.slice(0,6)}…${account.slice(-4)}`:'ウォレット未接続'; $('header-wallet').textContent=account?`${account.slice(0,6)}…${account.slice(-4)}`:'ウォレットを接続';$('connect').hidden=!!account;$('disconnect').hidden=!account; }
async function updateChain(){try{const chain=await provider.request({method:'eth_chainId'});$('chain-label').textContent=chain==='0x2105'?'Base Mainnet · 接続済み':`ネットワーク ${chain} · Baseではありません`;}catch{$('chain-label').textContent='ネットワークを確認できません';}}
const onAccounts=accounts=>{account=Array.isArray(accounts)&&/^0x[0-9a-fA-F]{40}$/.test(accounts[0])?accounts[0]:null;renderWallet();if(!account)$('chain-label').textContent='接続だけでは送金されません';};
const onChain=()=>updateChain();
const onDisconnect=()=>{account=null;renderWallet();$('chain-label').textContent='ウォレットの接続が解除されました';};
function unbind(){if(provider?.removeListener){provider.removeListener('accountsChanged',onAccounts);provider.removeListener('chainChanged',onChain);provider.removeListener('disconnect',onDisconnect);}}
async function connect(){if(account||connecting)return;connecting=true;$('connect').disabled=true;$('header-wallet').disabled=true;$('wallet-message').textContent='ウォレットを確認しています…';try{unbind();provider=window.ethereum||providers[0];if(!provider?.request)throw new Error('ブラウザ内のウォレットが見つかりません。ウォレット拡張機能、またはウォレットアプリ内のブラウザで開いてください。');const accounts=await provider.request({method:'eth_requestAccounts'});onAccounts(accounts);if(!account)throw new Error('接続できるアカウントがありません。');provider.on?.('accountsChanged',onAccounts);provider.on?.('chainChanged',onChain);provider.on?.('disconnect',onDisconnect);await updateChain();$('wallet-message').textContent='接続しました。署名・送金は行っていません。';}catch(e){$('wallet-message').textContent=e.code===4001?'接続をキャンセルしました。再度接続できます。':e.code===-32002?'ウォレットで接続リクエストを確認してください。':e.message||'接続できませんでした。もう一度お試しください。';}finally{connecting=false;$('connect').disabled=false;$('header-wallet').disabled=false;}}
$('connect').addEventListener('click',connect);$('header-wallet').addEventListener('click',()=>account?$('disconnect').focus():connect());$('disconnect').addEventListener('click',()=>{unbind();provider=null;account=null;renderWallet();$('chain-label').textContent='接続だけでは送金されません';$('wallet-message').textContent='このページの接続表示を解除しました。アクセス権の取り消しはウォレットから行えます。'});
document.querySelectorAll('[data-bot]').forEach(button=>button.addEventListener('click',()=>{selected=button.dataset.bot;document.querySelectorAll('[data-bot]').forEach(b=>{const active=b===button;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))});$('selected-name').textContent=selected+' BOT';$('lend-bot').textContent=selected;}));
function selectTab(name){for(const type of ['purchase','lending']){const active=type===name;$(type+'-tab').setAttribute('aria-selected',String(active));$(type+'-tab').tabIndex=active?0:-1;$(type+'-panel').hidden=!active;}}
for(const name of ['purchase','lending']){$(name+'-tab').addEventListener('click',()=>selectTab(name));$(name+'-tab').addEventListener('keydown',event=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const next=event.key==='Home'?'purchase':event.key==='End'?'lending':name==='purchase'?'lending':'purchase';selectTab(next);$(next+'-tab').focus();}});}
function parseUnits(value){if(!/^(0|[1-9]\d{0,11})(\.\d{1,6})?$/.test(value.trim()))return null;const [whole,fraction='']=value.trim().split('.');return BigInt(whole)*1000000n+BigInt(fraction.padEnd(6,'0'));}
function estimate(){const budget=parseUnits($('budget').value),daily=parseUnits($('daily').value);if(budget===null||daily===null||daily===0n){$('days').textContent='—';$('days-unit').textContent='';$('estimate-note').textContent='予算は0以上、日次費用は0より大きい数値を入力してください（小数6桁まで）';return;}$('days').textContent=(budget/daily).toLocaleString('ja-JP');$('days-unit').textContent='日';$('estimate-note').textContent='入力例による試算・端数切り捨て';}
$('budget').addEventListener('input',estimate);$('daily').addEventListener('input',estimate);
function review(kind){const lending=kind==='lending';const amount=parseUnits($('lend-amount').value);if(lending&&(amount===null||amount===0n)){$('lend-amount').setCustomValidity('0より大きいUSDC金額を、小数6桁以内で入力してください。');$('lend-amount').reportValidity();return;}$('review-title').textContent=lending?'貸付内容の確認':'購入内容の確認';const body=$('review-body');body.replaceChildren();const lines=lending?[['対象BOT',selected+' BOT'],['貸付希望額',$('lend-amount').value+' USDC'],['貸付先・契約・利率・返済期日','未設定'],['担保・出金条件・返済原資','未設定']]:[['選択中のBOT',selected+' BOT'],['購入価格・購入先・取得する権利','未設定'],['初期稼働予算','購入代金とは別に設定'],['稼働開始','決済確認と実行基盤の接続後']];const dl=document.createElement('dl');for(const [label,value]of lines){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;dl.append(dt,dd);}body.append(dl);$('review').showModal();}
$('lend-amount').addEventListener('input',()=>$('lend-amount').setCustomValidity(''));$('review-purchase').addEventListener('click',()=>review('purchase'));$('review-lending').addEventListener('click',()=>review('lending'));
